#!/bin/sh
# Capacity end-to-end window for the offline Pacer lab. Parent-run only.
#
#   PACER_CAPACITY_WINDOW=1 tests/lab/capacity-window.sh up|verify|down
#
# up (idempotent, run again after every CPA restart):
#   1. self-signed cert (SANs api.anthropic.com, platform.claude.com) in
#      $PACER_LAB_DIR/tls-capacity/, generated by openssl in a throwaway
#      network-none python:3.12-slim container if missing;
#   2. container pacer-upstream-capacity (python:3.12-slim, network pacer-lab,
#      no alias) running an immutable copy of capacity_upstream.py and the cert
#      dir, both read-only;
#   3. docker cp the cert to pacer-lab-cpa:/etc/ssl/certs/pacer-capacity-lab.pem,
#      which Go only loads at the next CPA start;
#   4. optional PACER_CAPACITY_PARK_ORIGINALS=1: move every non-cap login out
#      of /lab/auths (restored by down). Capacity membership needs every Claude
#      login of the CPA incarnation provider-verified, which the original
#      fixture logins can never be;
#   5. once CPA has started after steps 3/4 (otherwise it stops with STAGED):
#      save /etc/hosts to capacity-window/hosts.before, append api.anthropic.com
#      and platform.claude.com -> the fixture IP, then copy the cap logins.
# A CPA restart regenerates /etc/hosts: re-run up within ~20 s of every restart,
# before Pacer's first 30 s worker tick, or Claude reads reach the old fixture.
# verify: every piece above, including name resolution inside CPA and TLS.
# down: remove the logins, restore parked logins, restore hosts byte-for-byte,
# remove the CPA cert copy, stop and remove the fixture, print what was undone.
set -eu

if [ "${PACER_CAPACITY_WINDOW:-}" != 1 ]; then
	echo "capacity-window: refusing: the parent must own the lab and set PACER_CAPACITY_WINDOW=1" >&2
	exit 2
fi
command=${1:-}
case $command in up | verify | down) ;; *)
	echo "usage: PACER_CAPACITY_WINDOW=1 $0 up|verify|down" >&2
	exit 2
	;;
esac

here=$(cd "$(dirname "$0")" && pwd)
lab=${PACER_LAB_DIR:-$(cd "$here/../../../.." && pwd)/.cache/lab}
state="$lab/capacity-window"
certs="$lab/tls-capacity"
cpa=pacer-lab-cpa
fixture=pacer-upstream-capacity
network=pacer-lab
image=python:3.12-slim
marker='# pacer-capacity-window'
cpa_cert=/etc/ssl/certs/pacer-capacity-lab.pem
control=http://pacer-upstream-capacity.orb.local:8080
management=http://pacer-lab-cpa.orb.local:8317
logins="cap-a.json cap-b.json cap-c.json cap-d.json cap-e.json"
tmp=$(mktemp -d)
trap 'rm -rf "$tmp"' EXIT INT TERM

say() { printf 'capacity-window: %s\n' "$*"; }
die() {
	printf 'capacity-window: ERROR: %s\n' "$*" >&2
	exit 1
}
sha() { shasum -a 256 "$1" | cut -d' ' -f1; }
epoch() { # RFC 3339 (Docker StartedAt) -> integer seconds
	python3 -c 'import datetime,re,sys; s=re.sub(r"(\.\d{1,6})\d*", r"\1", sys.argv[1]).replace("Z","+00:00"); print(int(datetime.datetime.fromisoformat(s).timestamp()))' "$1"
}
running() { [ "$(docker inspect -f '{{.State.Running}}' "$1" 2>/dev/null)" = true ]; }
cpa_started() { epoch "$(docker inspect -f '{{.State.StartedAt}}' "$cpa")"; }
fixture_ip() { docker inspect -f '{{with index .NetworkSettings.Networks "pacer-lab"}}{{.IPAddress}}{{end}}' "$fixture" 2>/dev/null || true; }
read_file() { cat "$1" 2>/dev/null || true; }

preflight() {
	for tool in docker curl python3 shasum; do
		command -v "$tool" >/dev/null || die "$tool is required"
	done
	[ -d "$lab/auths" ] || die "$lab/auths does not exist; set PACER_LAB_DIR to the host directory mounted at /lab"
	docker network inspect "$network" >/dev/null 2>&1 || die "network $network does not exist"
	running "$cpa" || die "$cpa is not running"
	source=$(docker inspect -f '{{range .Mounts}}{{if eq .Destination "/lab"}}{{.Source}}{{end}}{{end}}' "$cpa")
	[ "$source" = "$lab" ] || die "$cpa mounts '$source' at /lab, not $lab"
	mkdir -p "$state"
	chmod 700 "$state"
}

ensure_cert() {
	if [ -f "$certs/cert.pem" ] && [ -f "$certs/key.pem" ]; then
		say "cert: reusing $certs/cert.pem ($(sha "$certs/cert.pem"))"
	else
		[ ! -e "$certs/cert.pem" ] && [ ! -e "$certs/key.pem" ] || die "$certs holds only half a key pair; inspect it"
		mkdir -p "$certs"
		chmod 700 "$certs"
		say "cert: generating a self-signed dummy cert in a throwaway network-none $image container"
		docker run --rm --pull=never --network none --label pacer.task=capacity-window \
			--mount "type=bind,src=$certs,dst=/out" "$image" \
			openssl req -x509 -newkey rsa:2048 -nodes -days 14 -subj /CN=api.anthropic.com \
			-addext 'subjectAltName=DNS:api.anthropic.com,DNS:platform.claude.com' \
			-keyout /out/key.pem -out /out/cert.pem
		chmod 600 "$certs/key.pem"
		chmod 644 "$certs/cert.pem"
		say "cert: generated $certs/cert.pem ($(sha "$certs/cert.pem"))"
	fi
	text=$(openssl x509 -in "$certs/cert.pem" -noout -text)
	for name in api.anthropic.com platform.claude.com; do
		printf '%s\n' "$text" | grep -q "DNS:$name" || die "cert lacks SAN $name"
	done
	openssl x509 -in "$certs/cert.pem" -noout -checkend 86400 >/dev/null || die "cert expires within a day; move $certs aside after down and run up again"
}

original_resets() { # upstream.py's reset constants as Pacer last observed them, or nothing
	curl -fsS --max-time 5 -H "Authorization: Bearer ${PACER_MANAGEMENT_KEY:-pacer-test-admin}" \
		"$management/v0/management/plugins/pacer/state" 2>/dev/null | python3 -c '
import datetime, json, re, sys
def epoch(s):
    s = re.sub(r"(\.\d{1,6})\d*", r"\1", s).replace("Z", "+00:00")
    return int(datetime.datetime.fromisoformat(s).timestamp())
found = {}
for a in json.load(sys.stdin).get("accounts", []):
    if a.get("provider") != "claude" or str(a.get("id", "")).startswith("cap-"):
        continue
    for w in a.get("windows", []):
        if w.get("scope") == "all" and w.get("seconds") in (18000, 604800) and w.get("reset"):
            found.setdefault(w["seconds"], set()).add(epoch(w["reset"]))
if all(len(found.get(s, ())) == 1 for s in (18000, 604800)):
    print(found[18000].pop(), found[604800].pop())
' 2>/dev/null || true
}

ensure_fixture() {
	copy="$state/capacity_upstream.py"
	if [ -f "$copy" ] && ! cmp -s "$copy" "$here/capacity_upstream.py"; then
		docker inspect "$fixture" >/dev/null 2>&1 && die "$copy differs from the source but $fixture exists; run down before loading new fixture source"
		chmod 600 "$copy"
		rm -f "$copy"
	fi
	if [ ! -f "$copy" ]; then
		cp "$here/capacity_upstream.py" "$copy"
		chmod 444 "$copy"
		say "fixture: immutable source copy $copy ($(sha "$copy"))"
	fi
	if docker inspect "$fixture" >/dev/null 2>&1; then
		mounts=$(docker inspect -f '{{range .Mounts}}{{.Source}}={{.Destination}} {{end}}' "$fixture")
		case $mounts in *"$copy=/app/capacity_upstream.py"*) ;; *) die "$fixture exists with unexpected mounts: $mounts" ;; esac
		case $mounts in *"$certs=/tls"*) ;; *) die "$fixture exists with unexpected mounts: $mounts" ;; esac
		if running "$fixture"; then
			say "fixture: $fixture already running"
		else
			docker start "$fixture" >/dev/null
			say "fixture: started existing $fixture (its counters restarted from zero)"
		fi
	else
		resets=$(original_resets)
		set -- --env FIXTURE_CERT=/tls/cert.pem --env FIXTURE_KEY=/tls/key.pem
		if [ -n "$resets" ]; then
			set -- "$@" --env "FIXTURE_ORIGINAL_FIVE_HOUR_RESET=${resets% *}" --env "FIXTURE_ORIGINAL_SEVEN_DAY_RESET=${resets#* }"
			say "fixture: original tokens answer upstream.py's observed resets ($resets)"
		else
			say "WARNING: original fixture resets unreadable from Pacer state; original tokens get start-relative resets"
		fi
		docker run -d --pull=never --name "$fixture" --label pacer.task=capacity-window \
			--network "$network" --read-only --restart no "$@" \
			--mount "type=bind,src=$copy,dst=/app/capacity_upstream.py,readonly" \
			--mount "type=bind,src=$certs,dst=/tls,readonly" \
			"$image" python -B /app/capacity_upstream.py >/dev/null
		say "fixture: created $fixture on $network (no alias)"
	fi
	i=0
	until curl -fsS --max-time 2 "$control/health" >/dev/null 2>&1; do
		i=$((i + 1))
		[ "$i" -lt 30 ] || die "$fixture did not become healthy within 30 s"
		sleep 1
	done
	[ -n "$(fixture_ip)" ] || die "$fixture has no $network address"
}

ensure_cpa_cert() {
	rm -rf "$tmp/cpa-cert"
	mkdir "$tmp/cpa-cert"
	if docker cp "$cpa:$cpa_cert" - 2>/dev/null | tar -x -C "$tmp/cpa-cert" 2>/dev/null &&
		cmp -s "$tmp/cpa-cert/$(basename "$cpa_cert")" "$certs/cert.pem"; then
		say "cert: $cpa:$cpa_cert already matches"
		[ -f "$state/cert-copied-at" ] || date +%s >"$state/cert-copied-at"
		return
	fi
	docker cp "$certs/cert.pem" "$cpa:$cpa_cert"
	date +%s >"$state/cert-copied-at"
	say "cert: copied to $cpa:$cpa_cert; Go loads it only at the next CPA start"
}

foreign_logins() {
	for path in "$lab/auths"/*.json; do
		[ -e "$path" ] || continue
		case $(basename "$path") in cap-?.json) ;; *) basename "$path" ;; esac
	done
}

park_originals() {
	mkdir -p "$state/parked-auths"
	chmod 700 "$state/parked-auths"
	for name in $(foreign_logins); do
		[ ! -e "$state/parked-auths/$name" ] || die "$state/parked-auths/$name already exists"
		printf '%s  %s\n' "$(sha "$lab/auths/$name")" "$name" >>"$state/parked-auths.sha256"
		mv "$lab/auths/$name" "$state/parked-auths/$name"
		date +%s >"$state/parked-at"
		say "parked: $name -> $state/parked-auths/ (restored by down)"
	done
}

restart_pending() { # prints why CPA must start again before hosts/logins, if it must
	started=$(cpa_started)
	copied=$(read_file "$state/cert-copied-at")
	parked=$(read_file "$state/parked-at")
	if [ -n "$copied" ] && [ "$started" -le "$copied" ]; then
		echo "the capacity cert was copied after CPA started"
	elif [ -n "$parked" ] && [ "$started" -le "$parked" ]; then
		echo "parked logins are still tombstones in this CPA incarnation"
	fi
}

hosts_lines() {
	ip=$1
	printf '%s api.anthropic.com %s\n%s platform.claude.com %s\n' "$ip" "$marker" "$ip" "$marker"
}

arm_hosts() {
	ip=$(fixture_ip)
	docker exec "$cpa" cat /etc/hosts >"$tmp/hosts.current"
	hosts_lines "$ip" >"$tmp/hosts.lines"
	if grep -qF "$marker" "$tmp/hosts.current"; then
		grep -F "$marker" "$tmp/hosts.current" | cmp -s - "$tmp/hosts.lines" || die "CPA /etc/hosts carries capacity lines for another address; run down first"
		say "hosts: already armed for $ip"
		return
	fi
	if [ -f "$state/hosts.before" ] && ! cmp -s "$tmp/hosts.current" "$state/hosts.before"; then
		keep="$state/hosts.before.$(date +%s)"
		mv "$state/hosts.before" "$keep"
		say "hosts: CPA /etc/hosts changed since the last arm (restart regenerated it); previous copy kept as $keep"
	fi
	[ -f "$state/hosts.before" ] || {
		cp "$tmp/hosts.current" "$state/hosts.before"
		chmod 600 "$state/hosts.before"
		say "hosts: saved $state/hosts.before ($(sha "$state/hosts.before"))"
	}
	docker exec -i "$cpa" sh -c 'cat >> /etc/hosts' <"$tmp/hosts.lines"
	date +%s >"$state/hosts-armed-at"
	say "hosts: appended api.anthropic.com and platform.claude.com -> $ip"
}

install_logins() {
	: >>"$state/installed-logins"
	for name in $logins; do
		if [ -e "$lab/auths/$name" ]; then
			say "logins: kept existing /lab/auths/$name (CPA rewrites it after its profile fetch)"
			continue
		fi
		cp "$here/capacity-auths/$name" "$lab/auths/.$name.tmp"
		chmod 600 "$lab/auths/.$name.tmp"
		mv "$lab/auths/.$name.tmp" "$lab/auths/$name"
		grep -qx "$name" "$state/installed-logins" || echo "$name" >>"$state/installed-logins"
		say "logins: installed /lab/auths/$name"
	done
}

write_window() {
	python3 - "$state/window.json" "$(cpa_started)" "$(read_file "$state/hosts-armed-at")" \
		"$(read_file "$state/cert-copied-at")" "$(read_file "$state/parked-at")" "$(fixture_ip)" "$(sha "$certs/cert.pem")" <<'EOF'
import json, sys
path, started, armed, copied, parked, ip, cert = sys.argv[1:]
num = lambda s: int(s) if s else None
with open(path, "w") as f:
    json.dump({"cpa_started_at": num(started), "hosts_armed_at": num(armed), "cert_copied_at": num(copied),
               "parked_at": num(parked), "fixture_ip": ip, "cert_sha256": cert}, f, indent=2)
    f.write("\n")
EOF
}

verify() {
	failed=0
	check() { # description, then a command
		description=$1
		shift
		if "$@" >/dev/null 2>&1; then say "verify ok:   $description"; else
			say "verify FAIL: $description"
			failed=1
		fi
	}
	ip=$(fixture_ip)
	check "$fixture running with address '$ip'" running "$fixture"
	check "fixture control $control/health" curl -fsS --max-time 3 "$control/health"
	for name in api.anthropic.com platform.claude.com; do
		check "fixture TLS for $name with the capacity cert" curl -fsS --max-time 3 --cacert "$certs/cert.pem" \
			--connect-to "$name:443:pacer-upstream-capacity.orb.local:443" "https://$name/health"
	done
	docker exec "$cpa" cat /etc/hosts >"$tmp/hosts.current" 2>/dev/null || : >"$tmp/hosts.current"
	hosts_lines "$ip" >"$tmp/hosts.lines"
	check "CPA /etc/hosts lines match $ip" sh -c 'grep -F "$1" "$2" | cmp -s - "$3"' sh "$marker" "$tmp/hosts.current" "$tmp/hosts.lines"
	for name in api.anthropic.com platform.claude.com; do
		resolved=$(docker exec "$cpa" getent hosts "$name" 2>/dev/null | cut -d' ' -f1 || true)
		check "CPA resolves $name to $ip (got '$resolved')" test -n "$ip" -a "$resolved" = "$ip"
	done
	docker cp "$cpa:$cpa_cert" - 2>/dev/null | tar -x -C "$tmp" 2>/dev/null || true
	check "CPA $cpa_cert matches $certs/cert.pem" cmp -s "$tmp/$(basename "$cpa_cert")" "$certs/cert.pem"
	pending=$(restart_pending)
	check "CPA started after the cert copy and any parking${pending:+ ($pending)}" test -z "$pending"
	for name in $logins; do
		check "login /lab/auths/$name present" test -f "$lab/auths/$name"
	done
	foreign=$(foreign_logins | tr '\n' ' ')
	check "no unverifiable non-cap login in /lab/auths${foreign:+ (found: $foreign)}" test -z "$foreign"
	[ "$failed" = 0 ] || die "verify failed"
	write_window
	say "verify: all checks passed; window recorded in $state/window.json"
}

up() {
	preflight
	ensure_cert
	ensure_fixture
	ensure_cpa_cert
	if [ "${PACER_CAPACITY_PARK_ORIGINALS:-}" = 1 ]; then
		park_originals
	elif [ -n "$(foreign_logins)" ]; then
		say "WARNING: /lab/auths holds non-cap logins: $(foreign_logins | tr '\n' ' ')"
		say "WARNING: they stay unverified, so every capacity interval fails membership (unknown_account_ref_tuple)."
		say "WARNING: re-run with PACER_CAPACITY_PARK_ORIGINALS=1 before restarting CPA, or expect check-capacity to refuse."
	fi
	pending=$(restart_pending)
	if [ -n "$pending" ]; then
		say "STAGED: $pending. Hosts and logins are not armed yet, so nothing reaches the fixture."
		say "STAGED: next: docker restart $cpa && PACER_CAPACITY_WINDOW=1 $0 up"
		exit 0
	fi
	arm_hosts
	install_logins
	verify
}

down() {
	preflight
	undone=""
	if [ -f "$state/installed-logins" ]; then
		while IFS= read -r name; do
			[ -n "$name" ] || continue
			if [ -e "$lab/auths/$name" ]; then
				rm -f "$lab/auths/$name"
				undone="$undone
  removed /lab/auths/$name"
			fi
		done <"$state/installed-logins"
		rm -f "$state/installed-logins"
	fi
	for name in $logins; do
		[ ! -e "$lab/auths/$name" ] || say "WARNING: /lab/auths/$name was not installed by this script; left in place"
	done
	if [ -f "$state/parked-auths.sha256" ]; then
		while read -r digest name; do
			[ ! -e "$lab/auths/$name" ] || die "/lab/auths/$name exists; refusing to overwrite it with the parked copy"
			[ "$(sha "$state/parked-auths/$name")" = "$digest" ] || die "parked $name changed while parked"
			mv "$state/parked-auths/$name" "$lab/auths/$name"
			undone="$undone
  restored /lab/auths/$name ($digest)"
		done <"$state/parked-auths.sha256"
		mv "$state/parked-auths.sha256" "$state/parked-auths.restored-$(date +%s)"
		rmdir "$state/parked-auths" 2>/dev/null || true
		rm -f "$state/parked-at"
	fi
	if docker exec "$cpa" cat /etc/hosts >"$tmp/hosts.current" 2>/dev/null; then
		if grep -qF "$marker" "$tmp/hosts.current"; then
			[ -f "$state/hosts.before" ] || die "CPA /etc/hosts is armed but $state/hosts.before is missing"
			grep -vF "$marker" "$tmp/hosts.current" | cmp -s - "$state/hosts.before" || die "CPA /etc/hosts changed beyond the capacity lines; not overwriting it"
			docker exec -i "$cpa" sh -c 'cat > /etc/hosts' <"$state/hosts.before"
			docker exec "$cpa" cat /etc/hosts | cmp -s - "$state/hosts.before" || die "CPA /etc/hosts restore did not read back byte-for-byte"
			undone="$undone
  restored $cpa:/etc/hosts byte-for-byte from $state/hosts.before ($(sha "$state/hosts.before"))"
		else
			say "hosts: CPA /etc/hosts carries no capacity lines (never armed, or a restart regenerated it)"
		fi
		if docker exec "$cpa" test -e "$cpa_cert"; then
			docker exec "$cpa" rm -f "$cpa_cert"
			undone="$undone
  removed $cpa:$cpa_cert (CPA trusts it in memory until its next restart)"
		fi
		rm -f "$state/hosts-armed-at" "$state/cert-copied-at"
	else
		say "WARNING: cannot read $cpa /etc/hosts or its cert; restore them by hand from $state"
	fi
	if docker inspect "$fixture" >/dev/null 2>&1; then
		if running "$fixture"; then
			saved="$state/fixture-attempts-$(date +%s).json"
			if curl -fsS --max-time 5 "$control/_test/attempts" >"$saved"; then
				undone="$undone
  saved fixture counters to $saved (no tokens)"
			else
				rm -f "$saved"
			fi
		fi
		docker stop "$fixture" >/dev/null
		docker rm "$fixture" >/dev/null
		undone="$undone
  stopped and removed $fixture"
	fi
	say "down: undone:${undone:- nothing}"
	say "down: kept $certs (dummy cert) and $state (hosts.before, receipts) for audit"
}

"$command"
